create table if not exists public.election_governance_assurance_reviews(id uuid primary key default gen_random_uuid(),award_space_id uuid not null references public.award_spaces(id) on delete cascade,title text not null,scope text not null,review_period_start date,review_period_end date,assurance_level text not null default 'limited' check(assurance_level in('limited','reasonable')),status text not null default 'planned' check(status in('planned','in_review','completed','accepted')),lead_reviewer_id uuid references public.admins(id) on delete set null,independence_declaration text,overall_conclusion text,management_response text,target_completion_date date,started_at timestamptz,completed_at timestamptz,accepted_at timestamptz,accepted_by uuid references public.admins(id) on delete set null,created_by uuid references public.admins(id) on delete set null,created_at timestamptz not null default now());
create table if not exists public.election_governance_assurance_findings(id uuid primary key default gen_random_uuid(),award_space_id uuid not null references public.award_spaces(id) on delete cascade,assurance_review_id uuid not null references public.election_governance_assurance_reviews(id) on delete cascade,title text not null,description text not null,severity text not null check(severity in('low','medium','high','critical')),recommendation text not null,management_action text,owner_id uuid references public.admins(id) on delete set null,target_date date,status text not null default 'open' check(status in('open','in_progress','resolved','verified')),resolved_at timestamptz,verified_at timestamptz,verified_by uuid references public.admins(id) on delete set null,created_at timestamptz not null default now());
create index if not exists election_governance_assurance_reviews_idx on public.election_governance_assurance_reviews(award_space_id,status,created_at desc);
create index if not exists election_governance_assurance_findings_idx on public.election_governance_assurance_findings(award_space_id,status,severity,target_date);
alter table public.election_governance_assurance_reviews enable row level security;
alter table public.election_governance_assurance_findings enable row level security;
